(function(root){
  root.renderWorkmateDashboard=function({app,people,expected,sample,esc,W,A}){
    const data=root.WorkmateInsights.summarize(people,W,A);
    function bars(q){return `<div class="insight-bars">${q.ranked.map((o,i)=>`<div class="insight-option"><div class="insight-option-label"><span>${esc(o.text)}</span><strong>${o.count}명 <small>(${q.n?Math.round(o.count/q.n*100):0}%)</small></strong></div><div class="insight-track" aria-hidden="true"><span class="tone-${i}" style="width:${q.n?o.count/q.n*100:0}%"></span></div></div>`).join('')}</div>`;}
    function card(q,type){return `<article class="panel insight-card"><div class="flex spread"><span class="pill">${type==='consensus'?'같은 선택에 모였어요':'두 선택으로 갈렸어요'}</span><span class="micro">${q.id+1}번 · ${q.n}명 응답</span></div><h3>${esc(q.text)}</h3>${bars(q)}</article>`;}
    app.innerHTML=`<section class="page wide dashboard"><div class="eyebrow">TEAM FINDINGS</div><div class="flex spread"><div><h1>우리 팀에서 눈에 띄는 선택</h1><p class="sub">함께 고른 행동과 서로 다르게 고른 행동부터 살펴봐요.</p></div><a class="btn ghost small" href="#host">코드 취합으로</a></div>${sample?'<div class="sample-banner">샘플 모드 · 가상 멤버의 응답이에요.</div>':''}<div class="insight-summary"><div><strong>${data.n}<small> / ${esc(expected)}명</small></strong><span>현재 집계한 응답</span></div><div><strong>${data.consensus.length}<small>문항</small></strong><span>같은 선택이 ⅔ 이상</span></div><div><strong>${data.divided.length}<small>문항</small></strong><span>두 선택에 의견이 나뉨</span></div></div>${data.n!==expected?'<p class="notice">현재까지 등록된 응답의 중간 결과예요. 추가 응답에 따라 눈에 띄는 항목이 바뀔 수 있어요.</p>':''}${data.excluded?`<p class="notice">이전 설문 형식 ${data.excluded}명은 집계에서 제외했어요. 현재 네 가지 행동을 고르는 설문끼리만 비교해요.</p>`:''}${data.n<4?'<section class="panel"><h2>응답이 더 모이면 특징을 보여드릴게요</h2><p class="note-text">최소 4명부터 같은 선택에 모인 항목과 의견이 갈린 항목을 골라 보여줘요. 문항별 실제 응답은 아래에서 확인할 수 있어요.</p></section>':`<section aria-labelledby="consensus-title"><div class="insight-heading"><h2 id="consensus-title">많은 동료가 함께 고른 행동</h2><p class="micro">응답자의 ⅔ 이상이 같은 행동을 선택한 문항 중 비율이 높은 순서예요.</p></div><div class="insight-grid">${data.consensus.slice(0,3).map(q=>card(q,'consensus')).join('')||'<p class="note-text">같은 선택이 ⅔ 이상인 문항은 아직 없어요.</p>'}</div></section><section aria-labelledby="divided-title"><div class="insight-heading"><h2 id="divided-title">함께 이야기해보면 좋을 차이</h2><p class="micro">두 선택에 각각 30% 이상, 합계 80% 이상이 모이고 두 그룹의 차이가 20%p 이하인 문항이에요. 두 그룹의 인원이 비슷한 순서로 보여요.</p></div><div class="insight-grid">${data.divided.slice(0,3).map(q=>card(q,'divided')).join('')||'<p class="note-text">두 선택으로 뚜렷하게 나뉜 문항은 아직 없어요.</p>'}</div></section>`}<details class="panel insight-detail"><summary>전체 24문항 응답 자세히 보기</summary><label class="field-label" for="insight-question">살펴볼 문항</label><select class="input select" id="insight-question">${data.questions.map(q=>`<option value="${q.id}">${q.id+1}. ${esc(q.text)}</option>`).join('')}</select><div id="insight-question-chart" aria-live="polite"></div></details><p class="micro">현재 메이트 설문 24문항을 집계해요. 선택한 행동의 분포이며 동료의 능력이나 팀의 성과를 뜻하지 않아요.</p></section>`;
    const select=app.querySelector('#insight-question');
    const update=()=>{const q=data.questions.find(q=>q.id===+select.value);app.querySelector('#insight-question-chart').innerHTML=`<h3>${esc(q.text)}</h3><p class="micro">${q.n}명 응답</p>${bars(q)}`;};
    select.addEventListener('change',update);update();
  };
})(typeof window==='undefined'?globalThis:window);
